// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 startingBalance) public {
        startingBalance = bound(startingBalance, 0, 1 ether);

        vm.deal(address(this), startingBalance);
        if (startingBalance > 0) {
            (bool sent,) = address(c).call{value: startingBalance}("");
            require(sent, "funding failed");
        }

        address recipient = address(0xABCD);

        c.withdrawAll(recipient);

        assertTrue(address(c).balance == 0);
    }
}
